def cards(*items,caption=None):
 v={'type':'cards','items':[{'title':title,'lines':lines} for title,lines in items]}
 if caption:v['caption']=caption
 return v
def counters(a,b,kind='years',start=3,caption=''):
 return {'type':'counters','items':[{'label':'Your '+kind,'value':a,'from':start},{'label':('Ravi’s ' if kind=='years' else 'Other café’s ')+kind,'value':b,'from':start}], 'caption':caption}
def c(label,next,**variables):
 d={'label':label,'next':next}
 if variables:d['set']=variables
 return d
def cont(next,label='Continue'):return [c(label,next)]
s={}
def add(id,line,visual=None,choices=None,**kw):
 s[id]={'line':line,'mood':'thinking',**kw}
 if visual:s[id]['visual']=visual
 if choices:s[id]['choices']=choices
prison=cards(('Both stay silent',['You: 1 year · Ravi: 1 year']),('Only you confess',['You: 0 years · Ravi: 5 years']),('Only Ravi confesses',['You: 5 years · Ravi: 0 years']),('Both confess',['You: 3 years · Ravi: 3 years']),caption='Fictional deal · fewer years is your assigned goal. Zero = no prison years.')
base=cards(('Both keep usual prices',['You ₹5,000 · Other ₹5,000']),('Only you discount',['You ₹6,000 · Other ₹2,000']),('Only the other discounts',['You ₹2,000 · Other ₹6,000']),('Both discount',['You ₹3,000 · Other ₹3,000']),caption='Original café rules · daily profit after all stated costs.')
changed=cards(('Both keep usual prices',['You ₹5,000 · Other ₹5,000']),('Only you discount',['You ₹4,000 · Other ₹2,000']),('Only the other discounts',['You ₹2,000 · Other ₹4,000']),('Both discount',['You ₹1,000 · Other ₹1,000']),caption='New cost: every discounting café pays ₹2,000 extra. Usual prices pay none. Final daily profit shown.')
add('s01','You and Ravi robbed a jewellery store. You’re caught, in separate rooms. Your goal: fewer prison years. You control only your statement.',cards(('One fictional decision',['Neither sees the other’s final statement. No messages or enforceable agreement.']),('Your two statements',['Stay silent: refuse the deal. Confess: accept it and name Ravi.'])),cont('s02','Read the deal'),mood='speaking')
add('s02','Here’s the whole deal. Each of you seeks fewer years for yourself. What statement do you make?',prison,[c('Stay silent','s03',first='silent'),c('Confess','s03',first='confess')],note='Unscored personal statement. Assigned goal is not a moral judgment. Both conditional outcomes follow; Ravi is never selected reactively.')
add('s03',{'first=silent':'You stay silent. Your sentence depends on Ravi’s statement: 1 year if he stays silent; 5 if he confesses.','default':'You confess. Your sentence depends on Ravi’s statement: 0 years if he stays silent; 3 if he confesses.'},{'first=silent':cards(('Ravi stays silent',['Your silence → you 1 year, Ravi 1 year.']),('Ravi confesses',['Your silence → you 5 years, Ravi 0 years.'])),'default':cards(('Ravi stays silent',['Your confession → you 0 years, Ravi 5 years.']),('Ravi confesses',['Your confession → you 3 years, Ravi 3 years.']))},cont('s04','Try a what-if'),consequence=True)
add('s04','A what-if, not a new round: both confess, 3 years each. Ravi keeps confessing. If only you become silent, what happens to your years?',prison,[c('My years fall','s05',expect='fall'),c('My years stay the same','s05',expect='stay the same'),c('My years rise','s05',expect='rise')],note='Unscored bounded expectation captured before any solo-switch result. The personal statement is not misconception evidence.')
add('s05','Teach me your fix for 3 years each. Which statement change gets BOTH of you to 1 year? I’ll run exactly your change.',prison,[c('Change only my statement','s06',fix='you'),c('Change only Ravi’s statement','s06',fix='ravi'),c('Change both statements','s06',fix='both')],note='Teach-back claim is bounded, not AI graded. Changes are labelled comparison controls, not powers available to the prisoner.')
add('s06',{'fix=you':'You changed only your statement to silence. Ravi still confesses. Your years rise: 3 → 5. One change cannot deliver two silences.','fix=ravi':'You changed only Ravi’s statement to silence. You still confess. His years rise: 3 → 5. One change cannot deliver two silences.','default':'You changed both statements to silence. Both sentences fall: 3 → 1. This fix needs two changes; your own statement controls just one.'},{'fix=you':counters(5,0,caption='Both confess: 3 / 3 → only you silent: 5 / 0.'),'fix=ravi':counters(0,5,caption='Both confess: 3 / 3 → only Ravi silent: 0 / 5.'),'default':counters(1,1,caption='Both confess: 3 / 3 → both silent: 1 / 1.')},cont('s07','Check the other changes'),consequence=True)
add('s07','You expected your years to {{expect}}. With Ravi still confessing, your solo silence raises them: 3 → 5. Here’s the snag in the shared fix.',cards(('Change from both confessing: 3 / 3',['Only you silent → 5 / 0. Only Ravi silent → 0 / 5. Both silent → 1 / 1.']),('Hold Ravi’s statement fixed',['Ravi silent: your confession gives 0, your silence 1.','Ravi confessing: your confession gives 3, your silence 5.']),('Your incentive',['Confessing rewards you when Ravi is silent and costs you fewer years when he confesses.'])),cont('s08','Look from Ravi’s room'),note='All alternative changes remain visible in a mandatory comparison. Numbers are ordered you / Ravi. No retries or loops.')
add('s08','Ravi has the same pressure. Looking into his room helps us compare; it doesn’t let your character control him.',cards(('Hold your statement fixed',['You silent: Ravi’s confession gives him 0 years; his silence gives him 1.','You confessing: Ravi’s confession gives him 3 years; his silence gives him 5.']),('The shared result',['Both silent: 1 year each, better for both than 3 each. But 0 still beats 1 for either person.'])),cont('s09','Name the problem'))
add('s09','Both can prefer the shared fix while each has a reason to leave it. That’s the prisoner’s dilemma.',{'type':'concept','name':'Prisoner’s dilemma','definition':'Each person has an action that improves their own result whichever fixed action the other takes. Yet both taking it leaves both worse off than the other shared outcome. Here, confessing gives each fewer years in either case, but 3 each is worse than 1 each.'},cont('s10','Try another setting'),note='Conditional on the assigned goal and exact deal. Not a prediction that everyone confesses. Loyalty and fairness can be other goals; trust alone does not change 0 versus 1.')
add('s10','New role: you run a café. Today, seek the greatest own profit. Another nearby owner chooses independently; neither sees the other’s final choice. Your move?',base,[c('Run a discount','s11',cafe='discount'),c('Keep usual prices','s11',cafe='usual')],note='Fictional one-day model, not business evidence. Profit = money after costs; no future effects or unlisted costs. Goal explicitly changes from fewer years to more profit.')
add('s11',{'cafe=discount':'You run a discount. You earn ₹6,000 if the other keeps usual prices, or ₹3,000 if they discount. The same pressure appears here.','default':'You keep usual prices. You earn ₹5,000 if the other does too, or ₹2,000 if they discount. Now compare changing only your action.'},cards(('Your profit, other action fixed',['Other usual: your discount ₹6,000 > your usual ₹5,000.','Other discount: your discount ₹3,000 > your usual ₹2,000.']),('The other owner has the same comparison',['You usual: their discount ₹6,000 > their usual ₹5,000.','You discount: their discount ₹3,000 > their usual ₹2,000.'])),cont('s12','Teach the fox a fix'),consequence=True)
