add('s13',{'cafefix=solo':'You changed only your café to usual prices. Your profit falls ₹3,000 → ₹2,000; the other rises to ₹6,000. Their discount stayed in place.','default':'You changed both cafés to usual prices. Each profit rises ₹3,000 → ₹5,000. Both actions had to change.'},{'cafefix=solo':counters(2000,6000,'profit ₹',3000,'Original rules · before ₹3,000 / ₹3,000 → only you usual ₹2,000 / ₹6,000. Both usual would give ₹5,000 / ₹5,000.'),'default':counters(5000,5000,'profit ₹',3000,'Original rules · before ₹3,000 / ₹3,000 → both usual ₹5,000 / ₹5,000. Only you usual would give ₹2,000 / ₹6,000.')},cont('s14','Add one new cost'),consequence=True)
add('s14','Separate what-if: each café running a discount now pays ₹2,000 extra that day. Usual prices pay none. Everything else stays the same. Your move?',changed,[c('Run a discount','s15',new='discount'),c('Keep usual prices','s15',new='usual')],note='Changed profits disclosed before the action, never a surprise deduction. This is the actual changed-condition challenge.')
add('s15',{'new=discount':'You kept the discount. The new cost leaves ₹4,000 against usual prices or ₹1,000 against a discount—₹1,000 less than your alternative in either case. What changed the best move?','default':'You chose usual prices. You earn ₹5,000 against usual prices or ₹2,000 against a discount—₹1,000 more than discounting in either case. What changed the best move?'},cards(('New cost · your choice versus alternative',['Other usual: your usual ₹5,000; your discount ₹4,000.','Other discount: your usual ₹2,000; your discount ₹1,000.'])),[c('The cost changed discount profits','s16',reason='cost'),c('The cost changed the other’s choice','s16',reason='choice')],consequence=True,note='Reason linked to a disclosed rule. Both alternatives have parallel sentence structure; no scoring colours or verdict.')
add('s16',{'reason=cost':'You pointed to discount profits. Yes: ₹6,000 − ₹2,000 = ₹4,000. Usual prices still earn ₹5,000 against the same other action.','default':'You pointed to the other’s choice. The new rule doesn’t choose for them. Hold them at usual prices: discount now earns ₹6,000 − ₹2,000 = ₹4,000; usual still earns ₹5,000.'},cards(('What the cost changes',['Best action: discount → usual prices.','Usual wins ₹5,000 > ₹4,000 and ₹2,000 > ₹1,000.']),('Same for the other café',['Each now prefers usual prices in either fixed case. Both usual earns ₹5,000 each: the taught conflict is gone.'])),cont('s17','Give the fox one final instruction'),note='Worked successful path after every reason response. Even two misses (action and reason) receive a worked example before the following fresh fixed-other attempt. That attempt is supported practice, not independent transfer evidence.')
